function cleanScreeningText(v){let t=String(v||'').replace(/【暫定】/g,'（最新解析で要確認）').replace(/\s+/g,' ').trim();if(!t)return'';const m=t.match(/巡回目安[:：]\s*([^。]+)/);if(m)t=m[1].trim();t=t.replace(/^確認ポイント[:：]\s*[^。]{0,32}。\s*/,'').replace(/^データ表示[:：]\s*[^。]{0,42}。\s*/,'').replace(/^巡回[:：]\s*/,'').replace(/\s*仕様・(?:出典|解説)を開く\s*↗.*$/,'').replace(/^(?:設定1[^：:]{0,48}|公開期待値表[^：:]{0,48}|実戦値[^：:]{0,48}|初心者[^：:]{0,48}|暫定期待値表[^：:]{0,48})[：:]\s*/,'').replace(/^期待値\+?2,?000円(?:以上)?(?:目安)?(?:（[^）]*）)?[：:]?\s*/,'').trim();const parts=t.split(/。+/).map(x=>x.trim()).filter(Boolean);if(parts.length>1){const useful=parts.find(x=>/\d|スルー|リセット|ゾーン|深|残|pt|ポイント|天井|時短|ST/i.test(x));t=useful||parts[0]}t=t.replace(/\s*注意[:：].*$/,'').replace(/を\+?2,?000円目安(?:の相談ライン)?/g,'').replace(/を相談ライン/g,'').replace(/の一部ゾーン$/,'').trim();if(t.length>58){const short=t.match(/((?:通常|AT間|CZ間|ボーナス間|女神間|液晶|等価|5\.6枚|56枚|リセット|\d+スルー)[^。]{0,55})/);if(short)t=short[1].trim()}if(t.length>58)t=t.slice(0,55)+'…';return beginnerStrategyText(t)}
const CORE_SCREENING=[[/もんきたんv/,'350G～／特殊ヘルメットはG数不問'],[/甲鉄城のかばねり海門決戦/,'300G～／ST駆け抜け・特殊背景はG数不問'],[/東京喰種/,'液晶250G～／AT間500G～／夜更け等はG数不問'],[/北斗の拳転生の章2/,'600あべし～／特殊あべし表示は相談'],[/みりおんごっど神々の軌跡/,'GG間500G～／強いリセット根拠は別判定'],[/ごっどいたりざれくしょん/,'450G～／バカンス・AT駆け抜け等は相談'],[/すますろ北斗の拳$/,'500G～／ジャギステージ等は相談'],[/かぐや様は告らせたい/,'BIG後400G～／REG後250G～／前回不明400G～'],[/戦国乙女5/,'AT間実G400G～／5周期目～'],[/からくりさかす2/,'液晶600G～／女神間500G～／女神3スルー～'],[/東京りべんじゃず/,'AT間400G～／3スルー～／5周期目～']]
const JUGGLER_SCREENING=[[/まいじゃぐらv/,'累計3,000G～＋REG 1/290前後以下'],[/ふぁんきじゃぐら2/,'累計3,000G～＋REG 1/323前後以下'],[/ごごじゃぐら3/,'累計3,000G～＋REG 1/269前後以下'],[/はっぴじゃぐらviii/,'累計3,000G～＋REG 1/301前後以下'],[/じゃぐらがるずss/,'累計3,000G～＋REG 1/281前後以下'],[/みすたじゃぐら/,'累計3,000G～＋REG 1/291前後以下'],[/うるとらみらくるじゃぐら/,'累計3,000G～＋REG 1/323前後以下'],[/(?:ねお)?あいむじゃぐらex/,'累計3,000G～＋REG 1/315前後以下']]
function coreScreening(name,kind=''){if(kind!=='slot')return'';const n=normLite(strategyFor(name)?.name||name);for(const[re,text]of CORE_SCREENING)if(re.test(n))return text;return''}
function jugglerScreening(name,kind=''){if(kind!=='slot')return'';const n=normLite(name);for(const[re,text]of JUGGLER_SCREENING)if(re.test(n))return text;return''}
function screeningTextScore(v,source=''){const t=cleanScreeningText(v);if(!t)return-999;if(/未監査/.test(t))return-900;let n=0;if(/\d/.test(t))n+=55;if(/(?:G|回|pt|あべし|コレ|周期|スルー|残|天井)/i.test(t))n+=30;if(/(?:～|以上|以内|以下|対象外|不問|濃厚)/.test(t))n+=18;if(source==='strategy')n+=12;if(/条件が見える|明らかに深い|深い台|深め|毎周確認|複数の狙い軸|優先$/.test(t))n-=28;if(t.length<=58)n+=5;return n}
function screeningForMachine(name,kind='',strategy=null){const core=coreScreening(name,kind);if(core)return core;const jug=jugglerScreening(name,kind);if(jug)return jug;const s=strategy||strategyFor(name);if(s?.type==='no-g')return'G数狙い対象外（回転率・設定は別評価）';if(s?.type==='setting'&&!s?.edge)return'設定狙いのみ／G数だけでは対象外';const {screens}=priorityDb(),k=canonicalMachineKey(name,kind),rec=screens.get(k),candidates=[{v:s?.target,src:'strategy'},{v:rec?.target,src:'low'},{v:rec?.quick,src:'low'},{v:s?.check,src:'strategy'}].filter(x=>x.v&&!/未監査/.test(String(x.v)));if(candidates.length){candidates.sort((a,b)=>screeningTextScore(b.v,b.src)-screeningTextScore(a.v,a.src));const best=cleanScreeningText(candidates[0].v);if(best&&!/条件が見える台を優先|毎周確認|複数の狙い軸/.test(best)){const fixed=/(?:\d+(?:G|回|pt|あべし)?(?:～|以上|以下)|\d+スルー|残り\d+)/.test(best),vague=/深め|深い台|近い台|直前|優先/.test(best);if((fixed&&!vague)||/(G数狙い対象外|設定狙いのみ|G数不問)/.test(best))return best;if(fixed&&!/深め|深い台|近い台|直前/.test(best))return best;return`一次足切り未設定｜${best}`}const q=cleanScreeningText(rec?.quick||s?.check);if(q)return`一次足切り未設定｜${q}`}return'一次足切り未設定｜機種固有条件を確認'}
const OBS_RISK_TERMS=[
 [/リセット|設定変更|据え置き|宵越し|RAM/i,'リセット根拠'],
 [/前回|履歴|直前|終了後|AT後|ST後|ボーナス後|BIG後|REG後|駆け抜け|当選後/i,'前回・終了履歴'],
 [/スルー/i,'スルー履歴'],
 [/差枚|有利区間/i,'有利区間・差枚履歴'],
 [/モード|内部|高確|天国|前兆/i,'内部状態・モード'],
 [/短縮/i,'短縮契機'],
 [/交換|現金投資|持ちメダル/i,'交換条件・投資状態']
];
function observabilityHints(text){const t=String(text||''),out=[];for(const[re,label]of OBS_RISK_TERMS){if(re.test(t)&&!out.includes(label))out.push(label);if(out.length>=3)break}return out}
function screeningObservability(name,kind='',screen='',strategy=null){
 const s=strategy||strategyFor(name),a=lookAuditFor(name),t=String(screen||screeningForMachine(name,kind,s)||''),joined=[t].filter(Boolean).join(' ');
 if(a?.status==='対象区分確認')return{level:'na',label:'天井狙い対象外',detail:'この機種は天井・G数狙いの対象ではありません。終了画面などは設定判別の別情報として扱います。',hints:[]};
 if(s?.type==='no-g'||(s?.type==='setting'&&!s?.edge)||/G数狙い対象外|設定狙いのみ/.test(t))return{level:'na',label:'G数だけで判別しない',detail:'この機種はG数だけで着席候補を決めません。設定・技術介入など別の根拠が必要です。',hints:[]};
 if(a?.status==='主要位置保留')return{level:'indirect',label:'見るだけでは判別不可',detail:'一次足切りに必要な情報の表示位置・確認方法が未確定です。推測せず「不明」でChatGPTへ相談してください。',hints:['表示位置・確認方法']};
 if(/未監査|一次足切り未設定/.test(t))return{level:'unknown',label:'確認方法が未確定',detail:'一次足切りの確認方法を十分に監査できていません。見た目だけで着席候補と判断しないでください。',hints:['機種固有の確認方法']};
 const hints=observabilityHints(joined);
 const auditHard=/自己カウント|復元不可|直接表示(?:位置)?(?:は)?未確認|表示位置(?:は)?未確認|正確な位置(?:は)?未確認|後から確認.*未確認|直接表示なし|物理位置(?:は)?未確認/.test(String(a?.note||'')+' '+String(a?.check||''));
 if(hints.length||auditHard){const extra=hints.length?`追加で必要：${hints.join('・')}。`:'';return{level:'mixed',label:'追加情報が必要',detail:`現在の表示だけでは条件を確定できない要素があります。${extra}分からない項目は「不明」で相談してください。`,hints};}
 return{level:'direct',label:'その場で確認しやすい',detail:'一次足切りの主条件は現在の台表示から確認しやすい項目です。ただし、条件到達＝着席可ではなくA判定は別です。',hints:[]};
}
