function consultCheckForMachine(name,kind='',raw=''){if(jugglerScreening(name,kind))return '今日の累計G → BB回数 → REG回数 → 合算';const a=lookAuditFor(name);if(a?.check)return a.check;const s=String(strategyFor(name).check||''),r=String(raw||'');if(s&&!/未監査/.test(s)&&checkItems(s).length>=2)return s;return r||s}
function consultFieldsForMachine(name,kind='',check=''){const n=normLite(name);if(jugglerScreening(name,kind))return['今日の累計G','BB回数','REG回数','合算（分かれば）'];const rules=[[/(?:もんきたんv)/,['現在G','現在の周期','ヘルメット（ロゴ・人物）','リセット／AT終了後の状態']],[/東京喰種/,['液晶G（CZ間）','AT間実G','現在のステージ／特殊示唆','前回AT・CZの状況']],[/甲鉄城のかばねり海門決戦/,['ST間G','現在の周期','サブ液晶の背景／皮膜Lv','短縮状態の根拠（駆け抜け等）']],[/からくりさかす2/,['液晶G','女神間実G','AT間実G','女神スルー回数']],[/東京りべんじゃず/,['AT間G','東卍CHANCEスルー回数','現在の周期','現在pt']],[/戦国乙女5/,['AT間実G','現在の周期','巫女カウンター','リセット／AT後1周期目か']],[/戦国乙女4/,['現在G','ボーナススルー回数','巫女カウンター','AT終了直後／特殊ステージ']],[/北斗の拳転生の章2/,['現在あべし','天撃失敗後か','リセット根拠','モード／ゾーン示唆']],[/すますろ北斗の拳$/,['サブ液晶GAME','現在ステージ','リセット根拠','前回BB後の状況']],[/ごっどいたりざれくしょん/,['現在G','リセット根拠','AT駆け抜け／特殊状態','バカンス等の示唆']],[/かぐや様は告らせたい/,['現在G','前回ボーナス（BIG／REG）','CZスルー回数','特殊状態']]];for(const[re,fields]of rules)if(re.test(n))return fields;const a=checkItems(check).slice(0,4);return a.length?a:['現在のG数／pt／スルー等','特殊状態・示唆（あれば）']}
function numericField(label){const t=String(label||'');if(/(?:種類|種別|内訳|状態|ステージ|背景|示唆|根拠|ヘルメット|リセット|モード|BIG／REG|BIG\/REG|前回)/i.test(t))return false;return /(?:G|pt|あべし|累計|回数|BB回数|REG回数|合算|回転数|周期)$/i.test(t)||/^(?:現在G|液晶G|AT間|CZ間|ST間|女神間|ボーナス間)/i.test(t)}
function readableParts(v){const t=beginnerStrategyText(v),raw=String(t||'').trim();if(!raw)return[];let parts=raw.split(/。+|(?=注意[:：])|(?=重要[:：])/).map(x=>x.trim()).filter(Boolean);if(parts.length===1&&raw.length>70&&raw.includes('／'))parts=raw.split('／').map(x=>x.trim()).filter(Boolean);return parts.slice(0,8)}
