function beginnerStrategyText(v){return String(v??'').replace(/等価・持ちメダル(?=\s*\d)/g,'交換ロスなし／手元メダル：').replace(/等価交換(?=\s*\d)/g,'交換ロスなし：').replace(/等価(?=\s*\d)/g,'交換ロスなし：').replace(/5\.6枚現金(?=\s*\d)/g,'56枚=1000円交換・現金投資：').replace(/5\.6枚交換(?=\s*\d)/g,'56枚=1000円交換：').replace(/5\.6枚(?=\s*\d)/g,'56枚=1000円交換：').replaceAll('等価・持ちメダル','交換ロスなし／手元メダル').replaceAll('等価交換','交換ロスなし').replaceAll('等価','交換ロスなし').replaceAll('5.6枚現金','56枚交換・現金投資').replaceAll('5.6枚交換','56枚交換').replaceAll('5.6枚','56枚交換').replaceAll('固定相談ライン','一次足切り').replaceAll('固定足切り','一次足切り').replaceAll('相談ライン','一次足切り').replaceAll('即ヤメ','終了後すぐにやめる').replaceAll('非前兆','前兆演出中ではない状態').replaceAll('打ち出し','打ち始め').replaceAll('前任者','前に打っていた人').replaceAll('復元不可','あとから確認できない').replaceAll('別途加点','追加の有利材料として扱う').replaceAll('別途再評価','ほかの条件も含めて再判定').replaceAll('別評価','ほかの条件も含めて別に判断').replaceAll('深追い','条件が弱いまま追い続ける').replaceAll('フォロー','そこまで回して確認').replaceAll('【暫定】','（最新解析で要確認）').replaceAll('安全側で扱う','不明な点は有利に推測せず、条件を厳しめに扱う').replaceAll('安全側','不明な点を有利に見積もらない方').replaceAll('保守採用','より厳しい数値を採用').replaceAll('保守的に','条件を厳しめに')}
function targetForDisplay(s){const t=String(s?.target||'未監査'),fixed=/(?:\d+(?:G|回|pt|あべし)?(?:～|以上|以下)|\d+スルー|残り\d+)/.test(t),vague=/深め|深い台|近い台|直前|優先/.test(t);const need=s?.edge&&(!fixed||(vague&&!fixed));const out=need?`一次足切り未設定｜${t} 現在の状態をそのままChatGPTへ送って判定。`:t;return beginnerStrategyText(out)}
function storeTargetForDisplay(s,d,kind){const base=targetForDisplay(s);const p=d?.slotExchangeProfile;if(kind!=='slot'||!p||p.displayBasis!=='nonEqual56')return base;if(!/56枚=1000円交換/.test(base))return base;const exact56=Number(p.exchangePiecesPer1000)===56;return base.replaceAll('交換ロスなし／持ちメダル','参考（交換ロスなし／持ちメダル）').replaceAll('交換ロスなし','参考（交換ロスなし）').replaceAll('56枚=1000円交換・現金投資',exact56?'この店で使う基準（現金投資）':'交換率が未確定のため56枚交換として仮計算（現金投資）').replaceAll('56枚=1000円交換',exact56?'この店で使う基準':'交換率が未確定のため56枚交換として仮計算')}
