function beginnerGlossaryHtml(){return '<details class="hs-glossary"><summary>初心者用語を確認</summary><div class="hs-glossary-grid">'+[['一次足切り','ChatGPTへ相談する候補を拾う最低条件。着席OKの意味ではありません。'],['期待値','同じ条件を何度も繰り返したときの平均的な損益の目安。1回の勝敗を保証しません。'],['G','ゲーム数。台を何ゲーム回したかの数。'],['AT','主にメダルを増やす区間。機種ごとに名称や仕組みは違います。'],['CZ','ATやボーナス当選を狙うチャンス区間。CZ当選だけではAT確定でない機種もあります。'],['スルー','CZやボーナスがATにつながらず終了した回数。'],['リセット','設定変更などで台の内部状態が初期化・変更された状態。推測だけでリセット扱いしません。'],['据え置き','前日の内部状態を引き継いでいる状態。'],['宵越し','前日のゲーム数や状態を当日にも引き継いで考えること。'],['前兆','当たりやCZの可能性を示す演出が続いている区間。'],['示唆','確定ではなく、特定状態の可能性が高まる情報。'],['+α','記載Gぴったりではなく、前兆などで少し後に発動する場合があるという意味。'],['有利区間','スマスロ等の内部管理区間。見た目だけでは切替を断定できない機種があります。'],['差枚','払い出した枚数から投入した枚数を引いた差。'],['純増','ATなどで1Gあたり平均何枚増えるかの目安。'],['ST','決められた回数内で当たりや継続を狙う区間。'],['ART','ATに近い、メダルを増やしながら遊技する区間。'],['RUSH','連続当たりや出玉獲得を狙う区間の総称。'],['BIG/BB','比較的獲得枚数が多いボーナス。BBはBIG BONUSの略。'],['REG/RB','比較的獲得枚数が少ないボーナス。RBはREGULAR BONUSの略。'],['pt','ポイント。機種内の数値で、規定値到達が抽選契機になることがあります。'],['天井','一定G数・回数などに到達すると当たりやCZなどが発生する救済条件。'],['モード','天井や当たりやすさ等を決める内部状態。見た目だけで断定できない場合があります。'],['高確/低確','当たりやCZ抽選などが有利／通常になっている内部状態。'],['駆け抜け','AT・STなどで十分な当たりや上乗せがなく、そのまま終了すること。'],['技術介入','目押し等の技術で結果や機械割が変わる要素。'],['機械割','長期的な投入に対する払出の割合。100%を超えるほど理論上は有利。'],].map(x=>'<div><b>'+x[0]+'</b><span>'+x[1]+'</span></div>').join('')+'</div></details>'}
function addBeginnerGlossary(){const fn=location.pathname.split('/').pop()||'';if(!(/search\.html$/.test(fn)||/abashiri\.html$/.test(fn)||/_integrated_factchecked\.html$/.test(fn)))return;if(document.getElementById('hsBeginnerGlossary'))return;const wrap=document.createElement('section');wrap.id='hsBeginnerGlossary';wrap.className='hs-glossary-wrap';wrap.innerHTML=beginnerGlossaryHtml();const bar=document.getElementById('hsRateVisBar'),main=document.querySelector('main');if(bar)bar.insertAdjacentElement('afterend',wrap);else if(main)main.prepend(wrap);else document.body.prepend(wrap)}
