function getMemos(){try{return JSON.parse(localStorage.getItem(LS_MEMO)||'[]').filter(x=>x&&x.date===today())}catch(e){return[]}}
function saveMemos(a){try{localStorage.setItem(LS_MEMO,JSON.stringify(a))}catch(e){}}
function modal(){let m=document.getElementById('hsModal');if(m)return m;m=document.createElement('div');m.id='hsModal';m.className='hs-modal';m.innerHTML='<section class="hs-sheet" role="dialog" aria-modal="true"><div class="hs-sheethead"><strong id="hsModalTitle"></strong><button class="hs-close" type="button" aria-label="閉じる">×</button></div><div id="hsModalBody"></div></section>';document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m||e.target.closest('.hs-close'))m.classList.remove('open')});return m}
function openModal(title,html){const m=modal();m.querySelector('#hsModalTitle').textContent=title;m.querySelector('#hsModalBody').innerHTML=html;m.classList.add('open');return m}
function guideHtml(g){return `<div class="hs-guideText">写真は実際のホールで撮影した見え方です。数値の意味は機種カードの「確認順」「一次足切り」と合わせて確認してください。</div><div class="hs-photos">${g.photos.map(p=>`<figure class="hs-photo"><img src="${p.src}" alt="${esc(g.title)}の確認場所" loading="eager">${(p.markers||[]).map(m=>`<span class="hs-marker" style="left:${m.x}%;top:${m.y}%">${esc(m.t)}</span>`).join('')}<figcaption class="hs-guideText" style="margin:0;border-radius:0">${esc(p.caption)}</figcaption></figure>`).join('')}</div>`}
function openGuide(name){const g=getGuide(name);if(!g)return;openModal('見る場所｜'+g.title,guideHtml(g))}
function checkItems(check){let a=String(check||'').split(/\s*→\s*|。+/).map(x=>x.trim()).filter(Boolean);if(a.length<=1&&a[0]?.length>36)a=a[0].split(/\s*\/\s*/).map(x=>x.trim()).filter(Boolean);return a.slice(0,6)}
function copyText(text){if(navigator.clipboard&&window.isSecureContext)return navigator.clipboard.writeText(text);return new Promise((resolve,reject)=>{const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.focus();ta.select();try{document.execCommand('copy')?resolve():reject(new Error('copy failed'))}catch(e){reject(e)}finally{ta.remove()}})}
function showToast(message,tone='ok'){let t=document.getElementById('hsToast');if(!t){t=document.createElement('div');t.id='hsToast';t.className='hs-toast';t.setAttribute('role','status');t.setAttribute('aria-live','polite');document.body.appendChild(t)}clearTimeout(showToast.timer);t.textContent=message;t.classList.toggle('is-error',tone==='error');t.classList.add('show');showToast.timer=setTimeout(()=>t.classList.remove('show'),1800)}
function consultationPrompt(x){const lines=['HALL SCANから着席判断を依頼します。',`日時：${new Date().toLocaleString('ja-JP',{timeZone:'Asia/Tokyo',hour12:false})}`,`店舗：${x.store||'不明'}`,`機種：${x.machine}`,`種別：${kindLabel(x.kind)}`,`レート：${x.rate||'不明'}`];if(x.number)lines.push(`台番号：${x.number}`);const ob=screeningObservability(x.machine,x.kind,x.screening,x.strategy);lines.push('',`HALL SCANの一次足切り：${x.screening||'不明'}`,`現地判別：${ob.label}｜${ob.detail}`,'','現在の状態：');for(const row of x.states||[])lines.push(`- ${row.label}：${row.value||'不明'}`);if(x.note)lines.push(`- その他：${x.note}`);lines.push('','実戦当日の最新解析をWebで確認し、このプロジェクトの基準でA/B/C/D判定してください。Aだけ着席可とします。交換条件・残り営業時間・残り軍資金も考慮し、1日の総投資30,000円は絶対に超えない前提です。重要情報が不足する場合は、最重要の確認事項を1つだけ、台のどこを見れば分かるか初心者向けに具体的に指示してください。分からない項目は推測せず「不明」として扱ってください。');return lines.join('\n')}
function formContext(name,opt={}){const s=opt.strategy||strategyFor(name),kind=opt.kind||'slot',check=consultCheckForMachine(name,kind,opt.check||s.check||''),screening=opt.screening||screeningForMachine(name,kind,s);return{machine:name,store:opt.store||storeName(),kind,rate:opt.rate||'',check,screening,strategy:s}}
function openDecision(name,check,target,eligible=true,needsWeb=false,opt={}){openMemoForm(name,{...opt,check:check||opt.check,screening:cleanScreeningText(target)||opt.screening,focusConsult:true})}
function openMemoForm(name,opt={}){const ctx=formContext(name,opt),items=consultFieldsForMachine(name,ctx.kind,ctx.check),fields=items.map((label,i)=>{const numeric=numericField(label)?' inputmode="numeric"':'';return `<label>${esc(label)}<input name="state${i}"${numeric} placeholder="不明でもOK" autocomplete="off"></label>`}).join('');const m=openModal('着席判断を相談｜'+name,`<div class="hs-consult-lead"><b>一次足切り</b><strong>${esc(ctx.screening)}</strong><small>ここは着席ラインではありません。条件に該当した台だけ詳しく入力します。</small>${observabilityBoxHtml(name,ctx.kind,ctx.screening,ctx.strategy)}</div><form class="hs-form" id="hsMemoForm"><div class="hs-form-grid"><label>機種<input name="machine" value="${esc(name)}" readonly></label><label>台番号<input name="number" inputmode="numeric" placeholder="例 336"></label></div><div class="hs-form-checks"><b>この機種で確認する項目</b>${fields}</div><label>その他・気づいたこと<textarea name="note" placeholder="例：特殊ステージ、前回AT、表示が分からない等"></textarea></label><div class="hs-form-actions"><button class="hs-primary" type="submit" name="action" value="copy">ChatGPT相談文をコピー</button><button class="hs-secondary" type="submit" name="action" value="save">今日の候補に保存</button></div><div id="hsCopyResult" class="hs-copy-result" aria-live="polite"></div></form>`);m.querySelector('#hsMemoForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),states=items.map((label,i)=>({label,value:String(f.get('state'+i)||'').trim()})),entry={id:Date.now(),date:today(),store:ctx.store,page:location.pathname.split('/').pop(),machine:name,number:String(f.get('number')||'').trim(),state:states.map(x=>x.value).filter(Boolean).join(' / '),states,note:String(f.get('note')||'').trim(),kind:ctx.kind,rate:ctx.rate,check:ctx.check,screening:ctx.screening};const submitter=e.submitter?.value||'copy';if(submitter==='save'){const a=getMemos();a.unshift(entry);saveMemos(a);m.querySelector('#hsCopyResult').textContent='今日の候補に保存しました。';updateMemoFab();return}try{await copyText(consultationPrompt(entry));m.querySelector('#hsCopyResult').textContent='相談文をコピーしました。ChatGPTに貼り付けてください。';showToast('相談文をコピーしました')}catch(err){m.querySelector('#hsCopyResult').textContent='自動コピーできませんでした。ブラウザの権限を確認してください。';showToast('コピーできませんでした','error')}};}
function openMemoList(){const a=getMemos(),html=a.length?`<div class="hs-memo-list">${a.map(x=>`<div class="hs-memo-item"><strong>${esc(x.machine)}${x.number?'｜台 '+esc(x.number):''}</strong><small>${esc(x.store)}${x.state?'｜'+esc(x.state):''}${x.note?'<br>'+esc(x.note):''}</small><div class="hs-memo-row"><button type="button" data-copy="${x.id}">相談文をコピー</button><button type="button" data-del="${x.id}">削除</button></div></div>`).join('')}</div><button class="hs-toolbtn" style="margin-top:12px" id="hsClearMemos">今日のメモをすべて削除</button><div id="hsMemoResult" class="hs-copy-result"></div>`:'<div class="hs-empty">今日保存した台はありません。</div>';const m=openModal('今日の候補',html);m.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const x=getMemos().find(v=>String(v.id)===b.dataset.copy);if(!x)return;const states=Array.isArray(x.states)?x.states:[{label:'現在の状態',value:x.state||''}];try{await copyText(consultationPrompt({...x,states,kind:x.kind||'slot',screening:x.screening||'不明'}));const r=m.querySelector('#hsMemoResult');if(r)r.textContent='相談文をコピーしました。';showToast('相談文をコピーしました')}catch(e){showToast('コピーできませんでした','error')}});m.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{saveMemos(getMemos().filter(x=>String(x.id)!==b.dataset.del));openMemoList();updateMemoFab()});const c=m.querySelector('#hsClearMemos');if(c)c.onclick=()=>{saveMemos([]);openMemoList();updateMemoFab()};}
function updateMemoFab(){let b=document.getElementById('hsMemoFab');if(!b){b=document.createElement('button');b.id='hsMemoFab';b.className='hs-memo-fab';b.type='button';b.onclick=openMemoList;b.innerHTML='候補メモ <b>0</b>';document.body.appendChild(b)}const n=getMemos().length;b.querySelector('b').textContent=n;b.hidden=n===0;b.classList.toggle('has-items',n>0);}
function setPatrol(on){document.body.classList.toggle('hs-patrol',on);try{localStorage.setItem(LS_PATROL,on?'1':'0')}catch(e){}document.querySelectorAll('.hs-patrol-toggle').forEach(b=>{b.classList.toggle('on',on);b.setAttribute('aria-pressed',String(on));b.textContent=on?'巡回モード ON':'巡回モード'});document.querySelectorAll('.hs-patrol-help').forEach(x=>x.textContent=on?'ON：一次足切りと判別マークを強調中。⚠/⛔は見た目だけで決めず、必要情報を確認。条件未満は基本スキップ。':'ONで一次足切りを強調し、補助表示を減らして一覧をコンパクト化します。')}
function addPatrolToggle(){const target=document.querySelector('header')||document.querySelector('.v21-search-head .inner');if(!target||target.querySelector('.hs-patrol-toggle'))return;const wrap=document.createElement('div');wrap.className='hs-tools';wrap.innerHTML='<button type="button" class="hs-toolbtn hs-patrol-toggle">巡回モード</button><small class="hs-patrol-help">ONで一次足切りを強調し、補助表示を減らして一覧をコンパクト化します。</small>';target.appendChild(wrap);wrap.querySelector('button').onclick=()=>setPatrol(!document.body.classList.contains('hs-patrol'));let on=false;try{on=localStorage.getItem(LS_PATROL)==='1'}catch(e){}setPatrol(on)}
function machineData(name){try{if(typeof data!=='undefined'&&Array.isArray(data)){const hit=data.find(x=>x.name===name);if(hit)return hit}}catch(e){}const fn=location.pathname.split('/').pop()||'',sn=storeName();return LOWRATE().find(x=>x.name===name&&(((x.file||'').split('?')[0]===fn)||x.store===sn))||LOWRATE().find(x=>x.name===name)||{}}
function replaceConsultationLabels(root=document.body){if(!root)return;const re=/(座る目安|等価|5\.6枚|即ヤメ|非前兆|前任者|復元不可|別途加点|別途再評価|別評価|【暫定】|相談ライン|固定足切り|固定相談ライン)/;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>{const p=n.parentElement;if(!p||/^(SCRIPT|STYLE|TEXTAREA)$/.test(p.tagName))return NodeFilter.FILTER_REJECT;return re.test(n.nodeValue)?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT}}),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(n=>{let t=n.nodeValue.replaceAll('座る目安','一次足切り');n.nodeValue=beginnerStrategyText(t)})}
function decorateCards(){document.querySelectorAll('.card').forEach(card=>{if(card.dataset.hs315)return;const name=card.querySelector('.name')?.textContent.trim();if(!name)return;card.dataset.hs315='1';const d=machineData(name),kind=d.kind||'slot',rank=priorityForMachine(name,kind,d.rank),screen=screeningForMachine(name,kind);const rankEl=card.querySelector('.rank');if(rankEl){rankEl.classList.remove('S','A','B','C','D','X');rankEl.classList.add(rank);rankEl.dataset.hsPriority=rank;rankEl.textContent=rank}card.querySelectorAll('.v311-quick-label').forEach(x=>x.textContent='確認順：');card.querySelectorAll('.row .label').forEach(x=>{if(x.textContent.trim()==='座る目安')x.textContent='一次足切り'});const target=card.querySelector('.targetline');if(target){const label=target.querySelector('.v311-target-label,.v23-target-label');if(label)label.textContent='一次足切り';const textNodes=[...target.childNodes].filter(n=>n.nodeType===Node.TEXT_NODE);textNodes.forEach(n=>n.remove());target.append(document.createTextNode(screen))}const qa=lookAuditFor(name),quickEl=card.querySelector('.quick');if(qa&&quickEl){const ql=quickEl.querySelector('.v311-quick-label');if(ql){[...quickEl.childNodes].filter(n=>n.nodeType===Node.TEXT_NODE).forEach(n=>n.remove());quickEl.append(document.createTextNode(qa.check))}else quickEl.textContent='確認順：'+qa.check}const ob=document.createElement('div');ob.className='hs-card-observability';ob.innerHTML=observabilityBoxHtml(name,kind,screen,strategyFor(name));(target||card.querySelector('.quick')||card.querySelector('.head')).after(ob);const actions=document.createElement('div');actions.className='hs-card-actions';const g=getGuide(name);actions.innerHTML=`<span class="hs-checked${freshnessClass(qa?.checked||'2026-09-18')}">${esc(freshnessText(qa?.checked||'2026-09-18',qa?'表示監査':'低貸確認'))}</span>${g?'<button class="hs-toolbtn hs-photo-btn" type="button">📷 見る場所</button>':''}<button class="hs-toolbtn hs-judge-btn" type="button">着席判断を相談</button>`;ob.after(actions);if(g)actions.querySelector('.hs-photo-btn').onclick=e=>{e.stopPropagation();openGuide(name)};const check=auditedCheck(name,d.quick||d.check||card.querySelector('.quick')?.textContent.replace(/^まず見る：?/,'').trim()||strategyFor(name).check||'');actions.querySelector('.hs-judge-btn').onclick=e=>{e.stopPropagation();openMemoForm(name,{kind,rate:d.rate||'',check,screening:screen,focusConsult:true})};});}
function decorateSearch(){document.querySelectorAll('.v21-resultwrap').forEach(w=>{if(w.dataset.hs315)return;const name=w.querySelector('.name')?.textContent.trim();if(!name)return;w.dataset.hs315='1';const meta=w.querySelector('.meta')?.textContent||'',kind='slot',rate=w.dataset.rate||'',store=w.dataset.store||meta.split('·')[1]?.trim()||'',s=strategyFor(name),check=auditedCheck(name,w.dataset.check||s.check||''),screen=w.dataset.screen||screeningForMachine(name,kind,s),a=document.createElement('div');a.className='hs-search-actions';const g=getGuide(name);a.innerHTML=`${g?'<button class="hs-toolbtn hs-photo-btn" type="button">📷 見る場所</button>':''}<button class="hs-toolbtn hs-consult-btn" type="button">着席判断を相談</button>`;w.appendChild(a);if(g)a.querySelector('.hs-photo-btn').onclick=()=>openGuide(name);a.querySelector('.hs-consult-btn').onclick=()=>openMemoForm(name,{kind,rate,store,check,screening:screen,focusConsult:true});});}
function addVisualGuide(){if(!/visual-guide\.html$/.test(location.pathname)||document.getElementById('hsOwnPhotos'))return;const sec=document.createElement('section');sec.id='hsOwnPhotos';sec.className='hs-visual-section';sec.innerHTML='<div class="v21-sectionhead"><b>実機写真｜見る場所</b><span>自前写真</span></div>'+PHOTO_GUIDES.map(g=>`<article class="hs-visual-card"><img src="${g.photos[0].src}" alt="${esc(g.title)}" loading="lazy"><div class="txt"><b>${esc(g.title)}</b><p>${esc(g.photos[0].caption)}</p><button type="button" class="hs-toolbtn" data-guide="${esc(g.title)}" style="margin-top:8px">見る場所を開く</button></div></article>`).join('');const main=document.querySelector('main')||document.body;main.prepend(sec);sec.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>openGuide(b.dataset.guide));}

function getRateVisibility(){try{const v=JSON.parse(localStorage.getItem(LS_RATE_VIS)||'null');if(v&&typeof v.normal==='boolean'&&typeof v.low==='boolean')return{normal:v.normal,low:v.low}}catch(e){}return{normal:true,low:true}}
function updateRateVisibilityUI(v){document.body.classList.remove('hs-view-low','hs-view-edge','hs-view-all','hs-low-only');document.body.classList.toggle('hs-hide-normal',!v.normal);document.body.classList.toggle('hs-hide-low',!v.low);document.querySelectorAll('.hs-ratevis-btn').forEach(b=>{const k=b.dataset.ratevis,on=!!v[k];b.classList.toggle('on',on);b.setAttribute('aria-pressed',String(on));const st=b.querySelector('span');if(st)st.textContent=on?'表示中':'非表示'});const empty=document.getElementById('hsRateEmpty');if(empty)empty.hidden=v.normal||v.low}
function setRateVisibility(v,save=true){const next={normal:v?.normal!==false,low:v?.low!==false};if(save)try{localStorage.setItem(LS_RATE_VIS,JSON.stringify(next))}catch(e){}updateRateVisibilityUI(next);document.dispatchEvent(new CustomEvent('hallscan-ratechange',{detail:next}));try{if(/search\.html$/.test(location.pathname)&&typeof render==='function')render()}catch(e){}}
function toggleRateVisibility(kind){const v=getRateVisibility();v[kind]=!v[kind];setRateVisibility(v)}
function addRateVisibilityBar(){const fn=location.pathname.split('/').pop()||'index.html';if(!(/search\.html$/.test(fn)||/stores\.html$/.test(fn)||/abashiri\.html$/.test(fn)||/_integrated_factchecked\.html$/.test(fn)))return;if(document.getElementById('hsRateVisBar'))return;const bar=document.createElement('section');bar.id='hsRateVisBar';bar.className='hs-ratevisbar';bar.innerHTML='<div class="hs-ratevis-copy"><b>レート表示</b><small>両方ONが通常表示</small></div><div class="hs-ratevis-segments" role="group" aria-label="表示する貸玉レート"><button type="button" class="hs-ratevis-btn" data-ratevis="normal"><b>通常レート</b><span>表示中</span></button><button type="button" class="hs-ratevis-btn" data-ratevis="low"><b>低貸</b><span>表示中</span></button></div><div id="hsRateEmpty" class="hs-ratevis-empty" hidden>通常レートと低貸が両方とも非表示です。上のボタンから表示するレートを選んでください。</div>';const header=document.querySelector('header');if(header)header.insertAdjacentElement('afterend',bar);else document.body.prepend(bar);bar.querySelectorAll('.hs-ratevis-btn').forEach(b=>b.onclick=()=>toggleRateVisibility(b.dataset.ratevis));updateRateVisibilityUI(getRateVisibility())}
function tagLowRateContent(){const fn=location.pathname.split('/').pop()||'';const isStore=/abashiri\.html$/.test(fn)||/_integrated_factchecked\.html$/.test(fn);if(isStore){const main=document.querySelector('main');if(main)[...main.children].forEach(el=>{if(!el.classList.contains('v311-help'))el.classList.add('hs-lowrate-content')});if(/abashiri\.html$/.test(fn)){document.querySelector('header input#search')?.classList.add('hs-lowrate-content')}else{document.querySelectorAll('header .sub,header .mode,header .search,header .filters').forEach(el=>el.classList.add('hs-lowrate-content'))}}if(/stores\.html$/.test(fn))document.querySelectorAll('.v21-storerow>div:nth-child(2)>span').forEach(el=>el.classList.add('hs-lowrate-label'))}
function normalFavKey(file,kind,rate,name){return `normal|${file}|${kind}|${rate}|${name}`}
function loadSharedFavs(){try{return new Set(JSON.parse(localStorage.getItem(NORMAL_FAV_KEY)||'[]'))}catch(e){return new Set}}
function saveSharedFavs(set){try{localStorage.setItem(NORMAL_FAV_KEY,JSON.stringify([...set]))}catch(e){}}
function currentStoreData(){const all=FULLRATE(),fn=location.pathname.split('/').pop()||'';if(fn==='abashiri.html'){const s=new URLSearchParams(location.search).get('store');return all['abashiri:'+s]||null}for(const d of Object.values(all)){if((d.file||'').split('?')[0]===fn)return d}return null}
function sourceLink(s){const u=s?.source||'',b=s?.benefitSource||'';const links=[];if(/^https?:\/\//.test(u)){const label=sourceNeedsWeb(s)?'設置確認元を開く ↗':'参照元を開く ↗';links.push(`<a class="hs-source-link" href="${esc(u)}" target="_blank" rel="noopener">${label}</a>`)}if(/^https?:\/\//.test(b)&&b!==u)links.push(`<a class="hs-source-link" href="${esc(b)}" target="_blank" rel="noopener">天井・出玉元を開く ↗</a>`);return links.join(' ')}
function detailField(label,val){if(!val||val==='—')return'';const parts=readableParts(val);return `<div class="hs-strategy-field"><b>${esc(label)}</b><p class="hs-readable">${parts.map(x=>`<span>${esc(x)}</span>`).join('')}</p></div>`}
function strategyCard(d,kind,rate,name,sharedFavs){const s=strategyFor(name),st=statusInfo(s),fk=normalFavKey(d.file,kind,rate,name),on=sharedFavs.has(fk),target=storeTargetForDisplay(s,d,kind),rank=priorityForMachine(name,kind),screen=screeningForMachine(name,kind,s),check=auditedCheck(name,s.check);return `<details class="hs-strategy-card hs-type-${st.cls}" data-edge="${s.edge?'1':'0'}"><summary><div class="hs-strategy-main"><div class="hs-strategy-title">${esc(name)}</div><div class="hs-screening"><span>一次足切り</span><strong>${esc(screen)}</strong><div class="hs-screening-observe">${observabilityBadgeHtml(name,kind,screen,s)}</div></div></div><div class="hs-strategy-side"><span class="hs-priority-mini">巡回 ${esc(rank)}</span><span class="hs-rate-chip">${esc(rate)}</span><span class="hs-status hs-status-${st.cls}">${esc(st.label)}</span><button type="button" class="hs-normal-fav${on?' on':''}" data-key="${esc(fk)}" aria-label="${on?'お気に入り解除':'お気に入り追加'}" aria-pressed="${on}">${on?'★':'☆'}</button></div></summary><div class="hs-strategy-detail">${observabilityBoxHtml(name,kind,screen,s)}${detailField('巡回ランク根拠',priorityExplanation(name,kind))}${detailField('確認順',check)}${detailField('表示監査',auditDetail(name))}${detailField('着席判断の参考',target)}${detailField('天井・条件',s.ceiling)}${detailField('天井到達時の恩恵',s.benefit)}${detailField('最低保証・注意',s.minimum)}${detailField('初期枚数・AT構造',s.initial)}${detailField('平均獲得目安',s.average)}${detailField('短縮・数え方',s.short)}${detailField('やめる目安',s.stop)}${detailField('注意',s.note)}${sourceCaution(s)}<div class="hs-strategy-foot"><span class="${freshnessClass(s.checked).trim()}">${esc(freshnessText(s.checked,'攻略確認'))}</span>${sourceLink(s)}</div><div class="hs-strategy-actions"><button type="button" class="hs-toolbtn hs-normal-judge">着席判断を相談</button></div></div></details>`}
function injectFullRateSection(){if(document.body.classList.contains('hs-unified-store'))return;const d=currentStoreData();if(!d||document.getElementById('hsFullRate'))return;const main=document.querySelector('main');if(!main)return;const machines=d.slot20||[];if(!machines.length){const sec=document.createElement('section');sec.id='hsFullRate';sec.className='hs-fullrate-section';sec.innerHTML=`<div class="hs-fullrate-head"><b>通常レート</b><small class="${freshnessClass(d.checked).trim()}">${esc(freshnessText(d.checked,'設置確認'))}｜20スロ掲載なし</small></div><div class="hs-fullrate-empty">現在の店舗掲載では20スロを確認できません。</div>`;main.appendChild(sec);return}const sec=document.createElement('section');sec.id='hsFullRate';sec.className='hs-fullrate-section';let limit=60,sharedFavs=loadSharedFavs();sec.innerHTML=`<div class="hs-fullrate-head"><b>通常レート｜${esc(d.store||'実戦情報')}</b><small class="${freshnessClass(d.checked).trim()}">${esc(freshnessText(d.checked,'設置確認'))}${d.sourceUpdated?'｜P-WORLD更新 '+esc(d.sourceUpdated):''}　${esc(freshnessText(STRATEGY().checked||STRATEGY_CHECKED,'攻略確認'))}</small><p>「期待値候補」は確認対象です。条件達成だけで座らず、ChatGPTへ現在の状態を送って着席判断してください。<br><b>判別マーク：</b> 👁その場で確認しやすい／⚠追加情報が必要／⛔見るだけでは判別不可。<br><b>交換表記：</b>「交換ロスなし」＝借りた時と交換時のメダル価値が同じ。「56枚=1000円交換」＝景品1000円分に56枚必要。交換率不明ならチャットで確認。${storeExchangeNote(d)?`<br><b>この店舗：</b>${esc(storeExchangeNote(d))}`:''}</p></div><div class="hs-fullrate-searchwrap"><input class="hs-fullrate-search" type="search" placeholder="20スロの機種名を検索" aria-label="20スロ設置機種を検索"></div><div class="hs-fullrate-count"></div><div class="hs-fullrate-list"></div><button type="button" class="hs-fullrate-more">続きを表示</button>`;main.appendChild(sec);const inp=sec.querySelector('.hs-fullrate-search'),list=sec.querySelector('.hs-fullrate-list'),cnt=sec.querySelector('.hs-fullrate-count'),more=sec.querySelector('.hs-fullrate-more');function getRows(){const raw=inp.value.trim();let arr=machines.map(n=>({name:n,s:strategyFor(n)}));if(raw)arr=arr.filter(o=>searchScore({name:o.name,store:d.store,quick:auditedCheck(o.name,o.s.check),target:o.s.target,rate:d.slotLabel,strategy:o.s},raw)>0);return arr}function draw(){const arr=getRows(),shown=arr.slice(0,limit),edgeCount=machines.filter(n=>strategyFor(n).edge).length;cnt.innerHTML=`<span>${esc(d.slotLabel||'20スロ')}</span><span>全${machines.length} / 候補${edgeCount}</span>`;list.innerHTML=shown.map(o=>strategyCard(d,'slot',d.slotLabel,o.name,sharedFavs)).join('')||'<div class="hs-fullrate-empty">該当する設置機種はありません。</div>';more.hidden=shown.length>=arr.length;more.textContent=`続きを表示（残り ${Math.max(0,arr.length-shown.length)}）`;list.querySelectorAll('.hs-normal-fav').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();const fk=b.dataset.key;sharedFavs.has(fk)?sharedFavs.delete(fk):sharedFavs.add(fk);saveSharedFavs(sharedFavs);draw()});list.querySelectorAll('.hs-normal-judge').forEach(b=>b.onclick=e=>{e.preventDefault();const det=b.closest('.hs-strategy-card'),name=det.querySelector('.hs-strategy-title')?.textContent||'',s=strategyFor(name);openMemoForm(name,{kind:'slot',rate:d.slotLabel,store:d.store,check:auditedCheck(name,s.check),screening:screeningForMachine(name,'slot',s),strategy:s,focusConsult:true})})}inp.addEventListener('input',()=>{limit=60;draw()});more.onclick=()=>{limit+=80;draw()};document.addEventListener('hallscan-ratechange',draw);const qp=new URLSearchParams(location.search).get('q');if(qp)inp.value=qp;draw()}
function addStoreNormalCounts(){if(!/stores\.html$/.test(location.pathname))return;const all=FULLRATE();document.querySelectorAll('.v21-storerow').forEach(row=>{if(row.querySelector('.hs-store-normal'))return;let d=null;const href=row.getAttribute('href')||'';if(/abashiri\.html/.test(href)){const s=new URL(href,location.href).searchParams.get('store');d=all['abashiri:'+s]}else{const fn=href.split('/').pop().split('?')[0];d=Object.values(all).find(x=>(x.file||'').split('?')[0]===fn)}if(!d)return;const box=document.createElement('div');box.className='hs-store-normal';const sl=d.slot20?.length||0,se=(d.slot20||[]).filter(n=>strategyFor(n).edge).length;box.dataset.s=sl;box.dataset.se=se;const txt=row.querySelector('div:nth-child(2)');if(txt)txt.appendChild(box)});function redraw(){document.querySelectorAll('.hs-store-normal').forEach(box=>{const s=+box.dataset.s,se=+box.dataset.se;box.innerHTML=s?`<span class="hs-rate-chip">20スロ ${s} / 候補${se}</span>`:'<span class="hs-unranked">通常レートなし</span>'})}redraw();document.addEventListener('hallscan-ratechange',redraw)}

const SEARCH_ALIASES={'東京ぐーる':'東京喰種','とうきょうぐーる':'東京喰種','ぐーる':'東京喰種','tokyoghoul':'東京喰種','りぜろ':'ゼロから始める異世界生活','もんきー':'モンキーターン','乙女4':'戦国乙女4','おとめ4':'戦国乙女4','乙女5':'戦国乙女5','おとめ5':'戦国乙女5','すますろ北斗':'スマスロ北斗の拳','すますろほくと':'スマスロ北斗の拳','かばねり':'甲鉄城のカバネリ','ごっどいーたー':'ゴッドイーター','からくり':'からくりサーカス','炎炎':'炎炎ノ消防隊','えんえん':'炎炎ノ消防隊','ヴヴヴ':'革命機ヴァルヴレイヴ','ゔゔゔ':'革命機ヴァルヴレイヴ','ばるぶれいぶ':'革命機ヴァルヴレイヴ','sao':'ソードアートオンライン','まどまぎ':'魔法少女まどかマギカ','えゔぁ':'エヴァンゲリオン','禁書':'とある魔術の禁書目録','きんしょ':'とある魔術の禁書目録','れーるがん':'とある科学の超電磁砲','りこりこ':'リコリスリコイル','じゃぐ':'ジャグラー'};
function lev(a,b){const n=a.length,m=b.length;if(Math.abs(n-m)>2)return 99;let prev=Array.from({length:m+1},(_,i)=>i);for(let i=1;i<=n;i++){const cur=[i];let rowMin=i;for(let j=1;j<=m;j++){cur[j]=Math.min(cur[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));rowMin=Math.min(rowMin,cur[j])}if(rowMin>2)return 99;prev=cur}return prev[m]}
function aliasTerm(q){const n=normLite(q),rows=Object.entries(SEARCH_ALIASES).map(([a,c])=>[normLite(a),normLite(c)]);for(const[a,c]of rows)if(a===n)return c;if(n.length>=4){for(const[a,c]of rows)if(Math.abs(a.length-n.length)<=1&&lev(n,a)<=1)return c}return n}
function fuzzyOneEdit(q,n){if(q.length<4||!n)return false;if(lev(q,n)<=1)return true;for(let l=Math.max(1,q.length-1);l<=q.length+1;l++)for(let i=0;i+l<=n.length;i++)if(lev(q,n.slice(i,i+l))<=1)return true;return false}
function dice(a,b){if(a.length<2||b.length<2)return a===b?1:0;const A=[],B=[];for(let i=0;i<a.length-1;i++)A.push(a.slice(i,i+2));for(let i=0;i<b.length-1;i++)B.push(b.slice(i,i+2));let hit=0,used=new Set;for(const x of A){const j=B.findIndex((y,i)=>y===x&&!used.has(i));if(j>=0){used.add(j);hit++}}return 2*hit/(A.length+B.length)}
function searchScore(x,raw){const q=normLite(raw);if(!q)return 1;const canon=aliasTerm(raw),name=normLite(x.name),hay=normLite([x.name,x.store,x.quick,x.target,x.rate,x.strategy?.ceiling,x.strategy?.benefit,x.strategy?.minimum,x.strategy?.initial,x.strategy?.average,x.strategy?.note].join(' '));if(name===q)return 1000;if(canon!==q&&name===canon)return 980;if(canon!==q&&name.startsWith(canon))return 950;if(canon!==q&&name.includes(canon))return 930;if(name.startsWith(q))return 910;if(name.includes(q))return 880;if(hay.includes(q)||hay.includes(canon))return 780;const f=canon!==q?canon:q;if(f.length>=4&&fuzzyOneEdit(f,name))return 680;if(f.length>=4&&dice(f,name)>=.72)return 620;return 0}
function normalSearchRows(){const out=[];for(const d of Object.values(FULLRATE()))for(const n of(d.slot20||[])){const s=strategyFor(n);out.push({area:d.area,store:d.store,file:d.file,kind:'slot',rank:priorityForMachine(n,'slot'),name:n,quick:s.check,target:screeningForMachine(n,'slot',s),rate:d.slotLabel,normalRate:true,checked:d.checked,strategy:s})}return out}
function installEnhancedSearch(){if(!/search\.html$/.test(location.pathname))return;try{if(typeof DATA==='undefined'||typeof render!=='function')return}catch(e){return}const normals=normalSearchRows(),low=DATA.filter(x=>x.kind==='slot'),oldKey=key,segs=[...document.querySelectorAll('.v21-segments [data-f]')],allBtn=segs.find(b=>b.dataset.f==='all');if(allBtn)allBtn.hidden=true;const segWrap=document.querySelector('.v21-segments');if(segWrap&&!document.getElementById('hsSearchPriorityHelp')){const note=document.createElement('small');note.id='hsSearchPriorityHelp';note.className='hs-patrol-help';note.textContent='巡回ランク＝期待値の強さ×再現性。S/Aほど先に確認しますが、着席判定ではありません。';segWrap.insertAdjacentElement('afterend',note)}function k2(x){return x.normalRate?normalFavKey(x.file,x.kind,x.rate,x.name):oldKey(x)}function priority(x){return PRIORITY_ORDER[priorityForMachine(x.name,'slot',x.rank)]??6}function syncSegments(){segs.forEach(b=>{const f=b.dataset.f,on=f==='slot'?true:f==='all'?false:filter===f;b.classList.toggle('on',on);b.setAttribute('aria-pressed',String(on))});q.placeholder='スロットから機種名・条件を検索'}render=function(){const raw=q.value.trim(),vis=getRateVisibility(),normalPool=vis.normal?normals:[],lowPool=vis.low?low:[],all=lowPool.concat(normalPool),a=all.map(x=>({x,score:searchScore(x,raw)})).filter(o=>{const x=o.x;if(x.kind!=='slot')return false;if(filter==='abashiri'&&x.area!=='網走')return false;if(filter==='kitami'&&x.area!=='北見')return false;if(filter==='fav'&&!favs.has(k2(x)))return false;return !raw||o.score>0}).sort((a,b)=>raw?(b.score-a.score)||priority(a.x)-priority(b.x)||a.x.name.localeCompare(b.x.name,'ja'):priority(a.x)-priority(b.x)||a.x.name.localeCompare(b.x.name,'ja')).map(o=>o.x);const limit=raw?320:120;count.textContent=`スロット ${a.length}件${a.length>limit?'（先頭'+limit+'件表示）':''}`;const shown=a.slice(0,limit);root.innerHTML=shown.map(x=>{const href='./'+x.file+(x.file.includes('?')?'&':'?')+'q='+encodeURIComponent(x.name),k=k2(x),on=favs.has(k),img=typeof machineImage==='function'?machineImage(x.name):'',s=x.strategy||strategyFor(x.name),st=x.normalRate?statusInfo(s):null,rank=priorityForMachine(x.name,'slot',x.rank),screen=screeningForMachine(x.name,'slot',s),check=auditedCheck(x.name,x.quick||s.check||''),meta=` · スロット${x.rate?' · '+esc(x.rate):''}${x.normalRate?' · '+esc(st.label):''}`;return `<div class="v21-resultwrap${x.normalRate?' hs-search-normal hs-type-'+st.cls:''}" data-kind="slot" data-rate="${esc(x.rate||'')}" data-store="${esc(x.store||'')}" data-check="${esc(check)}" data-screen="${esc(screen)}"><a class="v21-result" href="${href}">${img?`<div class="v32-machineThumb"><img src="${img}" alt="${esc(x.name)}の筐体" loading="lazy" width="96" height="128" onerror="this.closest('.v32-machineThumb').classList.add('is-broken');this.remove()"></div>`:`<div class="v21-rank ${esc(rank)}">${esc(rank)}</div>`}<div><div class="name">${esc(x.name)} <span class="hs-priority-mini">巡回 ${esc(rank)}</span></div><div class="meta">${esc(x.area)} · ${esc(x.store)}${meta}</div><div class="quick hs-search-screening"><span class="v23-target-label">一次足切り</span>${esc(screen)}<div class="hs-search-observe">${observabilityBadgeHtml(x.name,'slot',screen,s,true)}</div></div></div><div class="chev">›</div></a><button class="v21-fav ${on?'on':''}" type="button" data-key="${esc(k)}" aria-label="${on?'お気に入り解除':'お気に入り追加'}" aria-pressed="${on}">${on?'★':'☆'}</button></div>`}).join('');empty.textContent=(!getRateVisibility().normal&&!getRateVisibility().low)?'通常レートと低貸が両方とも非表示です。':filter==='fav'?'スロットのお気に入りはありません。':'スロットで該当する機種がありません。';empty.style.display=a.length?'none':'block';document.querySelectorAll('.v21-fav').forEach(b=>b.onclick=()=>{const kk=b.dataset.key;favs.has(kk)?favs.delete(kk):favs.add(kk);saveFavs();render()});syncSegments();decorateSearch();replaceConsultationLabels(root)};segs.forEach(b=>{b.onclick=null;const f=b.dataset.f;if(f==='all'||f==='slot')return;b.onclick=()=>{filter=filter===f?'all':f;try{saveSearchState()}catch(e){}render()}});syncSegments();render()}


function unifiedStoreContext(){
 const fn=location.pathname.split('/').pop()||'',all=FULLRATE(),lowAll=LOWRATE();
 if(!(fn==='abashiri.html'||/_integrated_factchecked\.html$/.test(fn)))return null;
 let normalStores=[],lowRows=[];
 if(fn==='abashiri.html'){
  normalStores=Object.values(all).filter(d=>d.area==='網走'||String(d.file||'').startsWith('abashiri.html'));
  lowRows=lowAll.filter(x=>String(x.file||'').startsWith('abashiri.html'));
 }else{
  normalStores=Object.values(all).filter(d=>(d.file||'').split('?')[0]===fn);
  const names=new Set(normalStores.map(d=>d.store));
  lowRows=lowAll.filter(x=>(x.file||'').split('?')[0]===fn||names.has(x.store));
 }
 return{fn,normalStores,lowRows};
}
function unifiedNormalRows(ctx){const out=[];for(const d of ctx.normalStores)for(const n of(d.slot20||[])){const s=strategyFor(n);out.push({source:'normal',area:d.area,store:d.store,file:d.file,kind:'slot',name:n,rate:d.slotLabel||'20スロ',rank:priorityForMachine(n,'slot'),quick:auditedCheck(n,s.check),target:screeningForMachine(n,'slot',s),strategy:s,checked:d.checked})}return out}
function unifiedLowRows(ctx){return ctx.lowRows.filter(x=>x.kind==='slot').map(x=>({source:'low',area:x.area,store:x.store,file:x.file,kind:x.kind,name:x.name,rate:x.rate||'',rank:priorityForMachine(x.name,x.kind,x.rank),quick:auditedCheck(x.name,x.quick||''),target:screeningForMachine(x.name,x.kind),strategy:null,checked:lookAuditFor(x.name)?.checked||'2026-09-18'}))}
function unifiedEntryPriority(e){return PRIORITY_ORDER[e.rank]??6}
function unifiedRateBadge(e){const base=e.source==='normal'?'通常':'低貸',r=String(e.rate||'').trim();return `<span class="hs-unified-rate ${e.source}">${base}${r?' '+esc(r):''}</span>`}
function unifiedSummaryBadges(entries){const seen=new Set,out=[];for(const e of entries){const k=e.source+'|'+String(e.rate||'').trim();if(seen.has(k))continue;seen.add(k);out.push(unifiedRateBadge(e))}return out.join('')}
function unifiedDetailEntry(e){const screen=screeningForMachine(e.name,e.kind,e.strategy);if(e.source==='low')return `<section class="hs-unified-entry low"><div class="hs-unified-entryhead">${unifiedRateBadge(e)}${e.store?`<span class="hs-unified-storetag">${esc(e.store)}</span>`:''}</div>${detailField('一次足切り',screen)}${observabilityBoxHtml(e.name,e.kind,screen,e.strategy||strategyFor(e.name))}${detailField('巡回ランク根拠',priorityExplanation(e.name,e.kind))}${e.quick?detailField('確認順',e.quick):''}${detailField('表示監査',auditDetail(e.name))}<div class="hs-strategy-actions"><button type="button" class="hs-toolbtn hs-unified-judge" data-name="${esc(e.name)}" data-kind="${esc(e.kind)}" data-rate="${esc(e.rate)}" data-store="${esc(e.store)}" data-check="${esc(e.quick)}" data-screen="${esc(screen)}">着席判断を相談</button></div></section>`;
 const s=e.strategy||strategyFor(e.name),st=statusInfo(s),d=(unifiedStoreContext()?.normalStores||[]).find(x=>x.store===e.store)||{},check=auditedCheck(e.name,s.check);return `<section class="hs-unified-entry normal"><div class="hs-unified-entryhead">${unifiedRateBadge(e)}<span class="hs-status hs-status-${st.cls}">${esc(st.label)}</span>${e.store?`<span class="hs-unified-storetag">${esc(e.store)}</span>`:''}</div>${detailField('一次足切り',screen)}${observabilityBoxHtml(e.name,e.kind,screen,s)}${detailField('巡回ランク根拠',priorityExplanation(e.name,e.kind))}${detailField('確認順',check)}${detailField('表示監査',auditDetail(e.name))}${detailField('着席判断の参考',storeTargetForDisplay(s,d,e.kind))}${detailField('天井・条件',s.ceiling)}${detailField('天井到達時の恩恵',s.benefit)}${detailField('最低保証・注意',s.minimum)}${detailField('平均獲得目安',s.average)}${detailField('やめる目安',s.stop)}${sourceCaution(s)}<div class="hs-strategy-foot"><span class="${freshnessClass(s.checked).trim()}">${esc(freshnessText(s.checked,'攻略確認'))}</span>${sourceLink(s)}</div><div class="hs-strategy-actions"><button type="button" class="hs-toolbtn hs-unified-judge" data-name="${esc(e.name)}" data-kind="${esc(e.kind)}" data-rate="${esc(e.rate)}" data-store="${esc(e.store)}" data-check="${esc(check||'')}" data-screen="${esc(screen)}">着席判断を相談</button></div></section>`}
function wrapLegacyStoreDetails(main){if(document.getElementById('hsLegacyStoreDetails'))return;const ids=['stats','cards','content','auditwrap','auditTitle','audit'];const nodes=ids.map(id=>document.getElementById(id)).filter(Boolean);if(!nodes.length)return;const det=document.createElement('details');det.id='hsLegacyStoreDetails';det.className='hs-legacy-details';det.innerHTML='<summary>従来の低貸詳細表示を開く</summary><div class="hs-legacy-details-body"></div>';main.appendChild(det);const body=det.querySelector('.hs-legacy-details-body');nodes.forEach(n=>{if(!body.contains(n))body.appendChild(n)});}
function unifiedPachinkoRateText(ctx){
 const all=FULLRATE();let d=null;
 if(ctx.fn==='abashiri.html'){
  let sid=new URLSearchParams(location.search).get('store')||'';
  try{if(typeof state!=='undefined'&&state?.store)sid=state.store}catch(e){}
  if(sid&&sid!=='all')d=all['abashiri:'+sid]||null;
 }else d=ctx.normalStores?.[0]||null;
 const rates=Array.isArray(d?.pachinkoRates)?d.pachinkoRates:[];
 if(!rates.length)return '';
 const checked=d?.pachinkoRateCheckedAt?`｜${d.pachinkoRateCheckedAt}確認`:'';
 return `パチンコ設置レート：${rates.join(' / ')}${checked}（レート情報のみ／機種データ非掲載）`;
}
function injectUnifiedStoreBrowser(){const ctx=unifiedStoreContext();if(!ctx||document.getElementById('hsUnifiedStore'))return false;const main=document.querySelector('main');if(!main)return false;const rows=unifiedLowRows(ctx).concat(unifiedNormalRows(ctx)).filter(e=>e.kind==='slot');if(!rows.length)return false;document.body.classList.add('hs-unified-store');wrapLegacyStoreDetails(main);const sec=document.createElement('section');sec.id='hsUnifiedStore';sec.className='hs-unified-store-area';sec.innerHTML='<div class="hs-unified-head"><div><b>店舗内機種一覧</b><small>パチスロ専用。通常レート＋低貸を統合。<br>一次足切り＝相談する最低ライン。巡回ランクは「期待値の強さ×再現性」で決定します。S/Aほど先に確認しますが、着席可否ではありません。<br><b>判別マーク：</b> 👁その場で確認しやすい／⚠追加情報が必要／⛔見るだけでは判別不可。</small><div class="hs-pachi-rate-meta" id="hsPachiRateMeta"></div></div><div class="hs-unified-search"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><circle cx="10.7" cy="10.7" r="6.2"/><path d="m15.3 15.3 4.7 4.7"/></svg><input type="search" id="hsUnifiedQ" placeholder="スロットから機種検索" autocomplete="off"></div><div class="hs-unified-meta" id="hsUnifiedMeta"></div></div><div class="hs-unified-list" id="hsUnifiedList"></div><button type="button" class="hs-fullrate-more" id="hsUnifiedMore">続きを表示</button>';
 const help=main.querySelector('.v311-help');if(help)help.insertAdjacentElement('afterend',sec);else main.prepend(sec);
 const q=sec.querySelector('#hsUnifiedQ'),list=sec.querySelector('#hsUnifiedList'),meta=sec.querySelector('#hsUnifiedMeta'),more=sec.querySelector('#hsUnifiedMore'),pachiMeta=sec.querySelector('#hsPachiRateMeta');let limit=80;
 function selectedRows(){let a=rows;if(ctx.fn==='abashiri.html'){let sid=new URLSearchParams(location.search).get('store')||'';try{if(typeof state!=='undefined'&&state?.store)sid=state.store}catch(e){}if(sid&&sid!=='all'){const d=FULLRATE()['abashiri:'+sid],lowNames={taiyo:'パーラー太陽 山下通店',royal:'ロイヤル網走店',maruhan:'マルハン網走店',towa:'TOWA 網走店'};a=a.filter(e=>e.source==='normal'?(d&&e.store===d.store):e.store===lowNames[sid])}}return a}
 function activeRows(){const vis=getRateVisibility();return selectedRows().filter(e=>e.source==='normal'?vis.normal:vis.low)}
 function grouped(){const raw=q.value.trim(),map=new Map;for(const e of activeRows()){if(raw&&searchScore({name:e.name,store:e.store,quick:e.quick,target:e.target,rate:e.rate,strategy:e.strategy},raw)<=0)continue;const k=canonicalMachineKey(e.name,'slot');if(!map.has(k))map.set(k,{name:e.name,kind:'slot',entries:[]});map.get(k).entries.push(e)}const a=[...map.values()];for(const g of a)g.entries.sort((x,y)=>unifiedEntryPriority(x)-unifiedEntryPriority(y)||(x.source==='low'?-1:1));return a.sort((a,b)=>Math.min(...a.entries.map(unifiedEntryPriority))-Math.min(...b.entries.map(unifiedEntryPriority))||a.name.localeCompare(b.name,'ja'))}
 function draw(){const gs=grouped(),shown=gs.slice(0,limit),vis=getRateVisibility(),lowCount=activeRows().filter(x=>x.source==='low').length,normCount=activeRows().filter(x=>x.source==='normal').length;pachiMeta.textContent=unifiedPachinkoRateText(ctx);pachiMeta.hidden=!pachiMeta.textContent;meta.innerHTML=`<span>スロット ${gs.length}機種</span><span>低貸 ${vis.low?lowCount:0}件 / 通常 ${vis.normal?normCount:0}件</span>`;list.innerHTML=shown.map(g=>{const rank=priorityForMachine(g.name,'slot',g.entries[0]?.rank),screen=screeningForMachine(g.name,'slot',g.entries.find(e=>e.strategy)?.strategy);return `<details class="hs-unified-card" data-kind="slot"><summary><div class="hs-unified-main"><div class="hs-unified-title">${esc(g.name)}</div><div class="hs-unified-badges"><span class="hs-kind-badge slot">スロット</span>${unifiedSummaryBadges(g.entries)}<span class="hs-priority-mini">巡回 ${esc(rank)}</span></div><div class="hs-screening"><span>一次足切り</span><strong>${esc(screen)}</strong><div class="hs-screening-observe">${observabilityBadgeHtml(g.name,'slot',screen,g.entries.find(e=>e.strategy)?.strategy||strategyFor(g.name))}</div></div></div><span class="hs-unified-chev">⌄</span></summary><div class="hs-unified-detail">${g.entries.map(unifiedDetailEntry).join('')}</div></details>`}).join('')||'<div class="hs-fullrate-empty">該当するスロット機種はありません。</div>';more.hidden=shown.length>=gs.length;more.textContent=`続きを表示（残り ${Math.max(0,gs.length-shown.length)}）`;list.querySelectorAll('.hs-unified-judge').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();openMemoForm(b.dataset.name,{kind:'slot',rate:b.dataset.rate,store:b.dataset.store,check:b.dataset.check,screening:b.dataset.screen,focusConsult:true})})}
 const legacySearch=document.getElementById('search');function syncLegacySearch(){if(!legacySearch)return;legacySearch.value=q.value;legacySearch.dispatchEvent(new Event('input',{bubbles:true}))}q.addEventListener('input',()=>{limit=80;syncLegacySearch();draw()});more.onclick=()=>{limit+=100;draw()};document.addEventListener('hallscan-ratechange',draw);if(legacySearch){const qp=new URLSearchParams(location.search).get('q');if(qp)q.value=qp;syncLegacySearch()}const storebar=document.getElementById('storebar');if(storebar)storebar.addEventListener('click',()=>setTimeout(()=>{limit=80;draw()},0));draw();return true}

function clarifyPriorityUI(root=document.body){if(!root)return;root.querySelectorAll('.rank,.v21-rank').forEach(el=>{if(el.dataset.hsPriorityApplied==='1')return;const r=(el.dataset.hsPriority||el.textContent||'').trim();if(!/^[SABCDX]$/.test(r))return;el.dataset.hsPriority=r;el.dataset.hsPriorityApplied='1';el.textContent='巡回 '+r;el.classList.add('hs-priority-rank');el.setAttribute('aria-label',`巡回優先度 ${r}。着席判断とは別です`);const a=el.closest('.v21-result');if(a)a.classList.add('hs-has-priority')});root.querySelectorAll('button[data-rank],button[data-r]').forEach(b=>{if(b.dataset.hsPriorityApplied==='1')return;const r=b.dataset.rank||b.dataset.r;if(/^[SABCDX]$/.test(r)){b.dataset.hsPriorityApplied='1';b.textContent='優先度 '+r;b.setAttribute('aria-label',`巡回優先度 ${r}で絞り込み`)}});root.querySelectorAll('.kpi span').forEach(el=>{if(el.textContent==='Sランク')el.textContent='巡回S';if(el.textContent==='Aランク')el.textContent='巡回A'});root.querySelectorAll('.sectionnote').forEach(el=>{if(/S＝最優先/.test(el.textContent)&&!el.dataset.hsPriorityNote){el.dataset.hsPriorityNote='1';el.textContent=el.textContent.replace('S＝最優先、A＝有力、B以下＝条件付き。','巡回ランク＝期待値の強さ×再現性。S/Aほど先に確認しますが、着席可否はChatGPTへ相談してください。')}});root.querySelectorAll('h2').forEach(el=>{if(/^巡回優先（S\/A）/.test(el.textContent))el.childNodes[0].nodeValue='巡回優先度（S/A） '})}
function annotateStaticFreshness(root=document.body){if(!root)return;root.querySelectorAll('.eyebrow,header .sub').forEach(el=>{if(el.dataset.hsFresh)return;const m=el.textContent.match(/(20\d{2}-\d{2}-\d{2})/);if(!m)return;el.dataset.hsFresh='1';const n=daysSince(m[1]);if(n!==null){el.textContent=el.textContent.replace(m[1],`${m[1]}時点・${n===0?'今日':n+'日前確認'}${n>=7?'・要再確認':''}`);if(n>=7)el.classList.add('hs-stale')}})}

const STAGE_REFERENCE_GUIDES_RAW=[
 {names:['L 東京喰種','東京喰種'],title:'東京喰種',items:[
  {label:'夜更け',art:'night-city',summary:'青黒い夜景ベースの暗いステージ。夜空・月・街灯やネオンの印象が強い。',points:['全体が暗めの青・紫系','月や夜景っぽい背景が見えやすい','通常の明るい街並みより夜寄りならメモ'],caution:'ステージ名だけで座らず、G数・前兆・他条件とセットで相談。'}
 ]}
];
let hsStageGuideIndex=null;
function stageGuideIndex(){if(hsStageGuideIndex)return hsStageGuideIndex;const idx={};for(const row of STAGE_REFERENCE_GUIDES_RAW)for(const n of(row.names||[]))idx[normLite(n)]=row;hsStageGuideIndex=idx;return idx}
function stageGuideForMachine(name){return null} // 実機ステージ画像はユーザー提供後に一括追加
function screeningPartsFromText(screen=''){let t=String(screen||'').replace(/^一次足切り未設定｜/,'').replace(/【[^】]*】/g,'').replace(/\s+/g,' ').trim();if(!t)return[];if(/^G数ハイエナ対象外|^G数狙い対象外|^設定狙い/.test(t))return[t];let parts=[];if(/\s*[／/]\s*/.test(t))parts=t.split(/\s*[／/]\s*/);else if(/(?:または|もしくは|いずれか|どれか1?つ|どちらか)\s*/.test(t))parts=t.split(/\s*(?:または|もしくは|いずれか|どれか1?つ|どちらか)\s*/);else if(/(?:かつ|且つ|両方|AND|＆|&)\s*/i.test(t))parts=t.split(/\s*(?:かつ|且つ|両方|AND|＆|&)\s*/i);parts=parts.map(x=>x.trim()).filter(Boolean);return parts.length?parts:[t]}
function screeningStructure(name,kind='',screen='',strategy=null){const s=strategy||strategyFor(name),raw=String(screen||screeningForMachine(name,kind,s)||'').trim();const parts=screeningPartsFromText(raw);const cleaned=raw.replace(/^一次足切り未設定｜/,'').trim();const explicitAnd=/(?:かつ|且つ|両方|すべて|全部|AND|＆|&)/i.test(cleaned);const explicitOr=/(?:または|もしくは|いずれか|どれか1?つ|どちらか|OR)/i.test(cleaned);let mode='single';if(parts.length>1){if(explicitAnd&&!explicitOr)mode='and';else if(explicitOr||/／|\//.test(cleaned))mode='or';else mode='or'}else if(/^G数ハイエナ対象外|^G数狙い対象外|^設定狙い/.test(cleaned))mode='na';const cfg={single:{badge:'単独条件',short:'単独',help:'この1条件を基準に相談候補を見ます。'},or:{badge:'OR条件',short:'OR',help:'下の条件はどれか1つを満たせば相談候補です。全部を同時に満たす必要はありません。'},and:{badge:'AND条件',short:'AND',help:'下の条件をすべて確認して、そろっていれば相談候補です。'},na:{badge:'対象外',short:'対象外',help:'G数だけでは着席候補にしません。'},mixed:{badge:'複合条件',short:'複合',help:'条件の読み方が複合です。詳細を見て判断してください。'}}[mode]||{badge:'複合条件',short:'複合',help:'条件の読み方が複合です。詳細を見て判断してください。'};return{raw,badge:cfg.badge,short:cfg.short,help:cfg.help,mode,parts:parts.length?parts:[cleaned||raw].filter(Boolean)}}
function screeningModeBadgeHtml(name,kind='',screen='',compact=false){const info=screeningStructure(name,kind,screen);return '<span class="hs-screening-mode hs-mode-'+info.mode+(compact?' compact':'')+'" title="'+esc(info.help)+'" aria-label="一次足切りの条件種類：'+esc(info.badge)+'">'+esc(compact?info.short:info.badge)+'</span>'}
function screeningFieldInnerHtml(name,kind='',screen=''){const info=screeningStructure(name,kind,screen);const modeText=info.mode==='or'?'どれか1つで相談候補':info.mode==='and'?'全部そろって相談候補':info.mode==='single'?'この1条件を確認':'G数だけでは判断しない';const partsHtml=info.parts.length>1?'<div class="hs-screening-parts hs-parts-'+info.mode+'">'+info.parts.map((p,i)=>(i&&info.mode==='or'?'<span class="hs-screening-sep">OR</span>':'')+(i&&info.mode==='and'?'<span class="hs-screening-sep and">AND</span>':'')+'<span class="hs-screening-pill">'+esc(p)+'</span>').join('')+'</div>':info.parts[0]?'<div class="hs-screening-parts hs-parts-single"><span class="hs-screening-pill">'+esc(info.parts[0])+'</span></div>':'';return '<div class="hs-screening-field"><div class="hs-screening-mode-row">'+screeningModeBadgeHtml(name,kind,screen)+'<small>'+esc(modeText)+'</small></div>'+partsHtml+'<div class="hs-screening-help">'+esc(info.help)+'</div></div>'}
function stageArtHtml(art,label){if(art==='night-city')return '<div class="hs-stage-art hs-stage-art-night" role="img" aria-label="'+esc(label)+'のイメージ図。夜の街並み。"><span class="moon"></span><span class="star s1"></span><span class="star s2"></span><span class="star s3"></span><span class="bldg b1"></span><span class="bldg b2"></span><span class="bldg b3"></span><span class="lamp l1"></span><span class="lamp l2"></span><span class="road"></span><span class="stage-name">'+esc(label)+'</span></div>';return '<div class="hs-stage-art" role="img" aria-label="'+esc(label)+'のイメージ図"><span class="stage-name">'+esc(label)+'</span></div>'}
function stageGuideFieldHtml(name){const g=stageGuideForMachine(name);if(!g||!g.items?.length)return'';return '<div class="hs-strategy-field hs-stage-field"><b>ステージ目印</b><div class="hs-stage-guides"><div class="hs-stage-guide-note">実機そのものではなく、色味・雰囲気をつかむための概略図です。</div>'+g.items.map(it=>'<article class="hs-stage-guide-card">'+stageArtHtml(it.art,it.label)+'<div class="hs-stage-guide-copy"><strong>'+esc(it.label)+'</strong><p>'+esc(it.summary||'')+'</p><ul>'+(it.points||[]).map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>'+(it.caution?'<small>'+esc(it.caution)+'</small>':'')+'</div></article>').join('')+'</div></div>'}
function machineNameFrom(el){if(!el)return'';const input=el.querySelector('input[name="machine"]');if(input?.value)return input.value.trim();const candidates=['.hs-strategy-title','.hs-unified-title','.name'];for(const sel of candidates){const node=el.querySelector(sel);if(node){const clone=node.cloneNode(true);clone.querySelectorAll('*').forEach(n=>n.remove());const t=clone.textContent.trim();if(t)return t}}const txt=el.textContent||'';return txt.trim()}
function machineKindFrom(el){const node=el.closest('[data-kind]')||el.querySelector('[data-kind]');return node?.dataset.kind||''}
function ensureSummaryMode(el){if(!el||el.dataset.hsScreeningMode==='1')return;const obs=el.querySelector('.hs-screening-observe,.hs-search-observe');let text='';const strong=el.querySelector('strong');if(strong)text=(strong.textContent||'').trim();else{const skip=new Set([obs,el.querySelector('.v23-target-label')]);for(const n of el.childNodes){if(skip.has(n))continue;if(n.nodeType===Node.TEXT_NODE)text+=n.nodeValue.trim();else if(n.nodeType===Node.ELEMENT_NODE&&!n.matches('.hs-search-meta,.hs-screening-meta,.hs-screening-observe,.hs-search-observe,.v23-target-label'))text+=n.textContent.trim()}text=text.trim()}if(!text)return;const name=machineNameFrom(el.closest('.hs-strategy-card,.hs-unified-card,.v21-resultwrap,.card,.hs-sheet,details,section,article,div'));const kind=machineKindFrom(el);const wrap=document.createElement('div');wrap.className=el.classList.contains('hs-search-screening')?'hs-search-meta':'hs-screening-meta';wrap.innerHTML=screeningModeBadgeHtml(name,kind,text,true);if(obs)wrap.appendChild(obs);if(strong)strong.insertAdjacentElement('afterend',wrap);else if(obs)obs.insertAdjacentElement('beforebegin',wrap);else el.appendChild(wrap);el.dataset.hsScreeningMode='1'}
function ensureDetailScreening(root=document.body){root.querySelectorAll('.hs-strategy-field').forEach(field=>{const label=field.querySelector('b');if(!label||label.textContent.trim()!=='一次足切り'||field.dataset.hsEnhanced==='1')return;const val=field.querySelector('p');if(!val)return;const text=val.textContent.trim();const name=machineNameFrom(field.closest('.hs-strategy-card,.hs-unified-entry,.hs-sheet,.card,details,section,article'));const kind=machineKindFrom(field);val.classList.add('hs-readable-rich');val.innerHTML=screeningFieldInnerHtml(name,kind,text);field.dataset.hsEnhanced='1';const host=field.parentElement;if(host&&!host.querySelector('.hs-stage-field'))field.insertAdjacentHTML('afterend',stageGuideFieldHtml(name))})}
function ensureConsultLead(root=document.body){root.querySelectorAll('.hs-consult-lead').forEach(box=>{if(box.dataset.hsEnhanced==='1')return;const strong=box.querySelector('strong');if(strong){const text=strong.textContent.trim();const name=machineNameFrom(box.closest('.hs-sheet')||box);const kind=machineKindFrom(box);const row=document.createElement('div');row.className='hs-consult-mode';row.innerHTML=screeningModeBadgeHtml(name,kind,text)+'<small>'+esc(screeningStructure(name,kind,text).help)+'</small>';strong.insertAdjacentElement('afterend',row);const stage=stageGuideFieldHtml(name);if(stage)box.insertAdjacentHTML('beforeend',stage)}box.dataset.hsEnhanced='1'})}
function ensureCardScreening(root=document.body){root.querySelectorAll('.hs-card-observability').forEach(box=>{if(box.dataset.hsEnhanced==='1')return;const card=box.closest('.card');const name=machineNameFrom(card||box);if(!name)return;const kind=machineKindFrom(card||box);let screen='';const target=card?.querySelector('.targetline');if(target)screen=target.textContent.replace('一次足切り','').trim();if(screen){box.insertAdjacentHTML('afterbegin','<div class="hs-strategy-field hs-inline-card-screen"><b>一次足切り</b>'+screeningFieldInnerHtml(name,kind,screen)+'</div>');const stage=stageGuideFieldHtml(name);if(stage)box.insertAdjacentHTML('beforeend',stage)}box.dataset.hsEnhanced='1'})}
function ensureLegacyTargetline(root=document.body){root.querySelectorAll('.targetline').forEach(el=>{if(el.dataset.hsMode==='1')return;const text=el.textContent.replace(/^一次足切り/,'').trim();if(!text)return;const name=machineNameFrom(el.closest('.card,.hs-sheet,details,section,article'));const kind=machineKindFrom(el);const badge=document.createElement('div');badge.className='hs-targetline-mode';badge.innerHTML=screeningModeBadgeHtml(name,kind,text,true)+'<small>'+esc(screeningStructure(name,kind,text).help)+'</small>';el.appendChild(badge);el.dataset.hsMode='1'})}
function ensureVisualGuideStages(){return} // 実機ステージ画像をまとめて受領後に有効化
function enhanceScreeningUI(root=document.body){root.querySelectorAll('.hs-screening,.hs-search-screening').forEach(ensureSummaryMode);ensureDetailScreening(root);ensureConsultLead(root);ensureCardScreening(root);ensureLegacyTargetline(root);ensureVisualGuideStages()}

